    likelihood_ratio = "likelihood_ratio"
    """
    A likelihood-ratio statistic, from comparing a model against a nested one.
    """
    beta = "beta"
    """
    A regression coefficient reported as the test statistic itself, which some papers do instead of giving a t or z.
    """
    correlation = "correlation"
    """
    A correlation coefficient reported as the statistic, r or rho.
    """


