    electrophysiological_amplitude = "electrophysiological_amplitude"
    """
    The size of a voltage or field deflection in the time domain, such as an evoked- potential peak.
    """
    electrophysiological_power = "electrophysiological_power"
    """
    Signal power in a frequency band. The band itself is not a field here; name it in specific_metric.
    """
    connectivity_strength = "connectivity_strength"
